Here's a minimal todo app using `useState`:

```jsx
import { useState } from "react";

export default function TodoApp() {
  const [todos, setTodos] = useState([]);
  const [text, setText] = useState("");

  function addTodo(e) {
    e.preventDefault();
    const trimmed = text.trim();
    if (!trimmed) return;
    setTodos([...todos, { id: Date.now(), text: trimmed, done: false }]);
    setText("");
  }

  function toggleTodo(id) {
    setTodos(todos.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));
  }

  return (
    <div style={{ maxWidth: 400, margin: "2rem auto", fontFamily: "sans-serif" }}>
      <h1>My Todos</h1>
      <form onSubmit={addTodo}>
        <input
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="What needs doing?"
        />
        <button type="submit">Add</button>
      </form>
      <ul>
        {todos.map((t) => (
          <li key={t.id}>
            <label style={{ textDecoration: t.done ? "line-through" : "none" }}>
              <input type="checkbox" checked={t.done} onChange={() => toggleTodo(t.id)} />
              {t.text}
            </label>
          </li>
        ))}
      </ul>
      <p>{todos.filter((t) => !t.done).length} left</p>
    </div>
  );
}
```

**How it works**
- `todos` holds the list; `text` holds the input value (a controlled input).
- `addTodo` creates a new object and replaces the array — never mutate state directly.
- `toggleTodo` flips `done` with `map`, which returns a new array.

