import { useState } from "react";

export default function TodoApp() {
  const [todos, setTodos] = useState([]);
  const [text, setText] = useState("");

  function addTodo(e) {
    e.preventDefault();
    if (!text.trim()) return;
    setTodos([...todos, { id: Date.now(), text: text.trim(), done: false }]);
    setText("");
  }

  function toggleTodo(id) {
    setTodos(todos.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));
  }

  function deleteTodo(id) {
    setTodos(todos.filter((t) => t.id !== id));
  }

  return (
    <div>
      <form onSubmit={addTodo}>
        <input value={text} onChange={(e) => setText(e.target.value)} />
        <button type="submit">Add</button>
      </form>
      <ul>
        {todos.map((t) => (
          <li key={t.id}>
            <input type="checkbox" checked={t.done} onChange={() => toggleTodo(t.id)} />
            {t.text}
            <button onClick={() => deleteTodo(t.id)} aria-label={`Delete ${t.text}`}>
              ✕
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

**What changed**
- `deleteTodo` uses `filter` to return a new array without that task.
- Each `<li>` gets a ✕ button; the arrow function passes the right `id`.
- `aria-label` makes the button readable by screen readers.

